package com.primehr.security;
import com.primehr.integration.administrative.*; import org.junit.jupiter.api.Test; import org.springframework.security.access.AccessDeniedException; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
class RspApplicationScreeningPermissionGuardTest {
 private final AdministrativeAuthorizationClient client=mock(AdministrativeAuthorizationClient.class);private final RspApplicationScreeningPermissionGuard guard=new RspApplicationScreeningPermissionGuard(client);
 @Test void exactActionsAndAgencyWideScopeAreRequired(){String token="Bearer token";when(client.resolve(RspApplicationScreeningPermissionGuard.FEATURE,token)).thenReturn(new EffectiveFeaturePermission(RspApplicationScreeningPermissionGuard.FEATURE,false,true,true,true,false,false,true,false,false,false,false,PermissionDataScope.AGENCY_WIDE));assertThatCode(()->guard.require(PrimeHrAction.ADD,token)).doesNotThrowAnyException();assertThatCode(()->guard.require(PrimeHrAction.EDIT,token)).doesNotThrowAnyException();assertThatCode(()->guard.require(PrimeHrAction.SUBMIT,token)).doesNotThrowAnyException();assertThatThrownBy(()->guard.require(PrimeHrAction.APPROVE,token)).isInstanceOf(AccessDeniedException.class);when(client.resolve(RspApplicationScreeningPermissionGuard.FEATURE,token)).thenReturn(new EffectiveFeaturePermission(RspApplicationScreeningPermissionGuard.FEATURE,false,true,true,true,false,false,true,true,false,false,false,PermissionDataScope.OWN_RECORDS));assertThatThrownBy(()->guard.require(PrimeHrAction.ACCESS,token)).isInstanceOf(AccessDeniedException.class);}
 @Test void administratorAndBearerRulesArePreserved(){assertThatThrownBy(()->guard.require(PrimeHrAction.ACCESS,"token")).isInstanceOf(AccessDeniedException.class);String token="Bearer admin";when(client.resolve(RspApplicationScreeningPermissionGuard.FEATURE,token)).thenReturn(new EffectiveFeaturePermission(RspApplicationScreeningPermissionGuard.FEATURE,true,false,false,false,false,false,false,false,false,false,false,PermissionDataScope.NONE));assertThatCode(()->guard.require(PrimeHrAction.APPROVE,token)).doesNotThrowAnyException();}
}
